class Question(ChatbotAction):
    def __init__(self):
        super(Question, self).__init__()
        self.name = ChatbotAction.__name__


class Response(ChatbotAction):
    def __init__(self):
        super(Response, self).__init__()
        self.name = ChatbotAction.__name__

    def __call__(self, state: State, message: Message) -> Message:
        prompt = state.get(self.name)
        if prompt is None:
            # Should not happen
            return message
        return message.clone_by(prompt=prompt)


class Chatbot(ActionManager):
    state: State
    response: Response
    question: Question
    question_score: State = State(5)

